import {rooms} from './world-layout.js';
import {readState,writeState,recordAnswer,dueItems,learningChange,loadCatalog} from './learning-core.js';
import {toss,montyTrial,montyBatch,bridgeOpen,barHeight,seasonModel} from './simulations.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#learning'),warning=document.querySelector('#save-warning');
let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error()},setItem(){throw Error()}};}
const loaded=readState(storage);let state=loaded.state,items=[],cached=false,error='',screen='catalog',room='all',featured=true,search='',current=null,review=false,opener=null,loadPending=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roomName=id=>rooms.find(r=>r.id===id)?.name||'학습실';
function notifySave(message){warning.hidden=!message;warning.textContent=message||'';}
function persist(){notifySave(writeState(storage,state));}
if(loaded.error)notifySave(loaded.error);
function draft(){const key=current.id+(review?'-review':'');return state.drafts[key]||(state.drafts[key]={choice:null,hints:0,note:'',committed:false,evidence:false,simulation:{}});}
function itemView(){if(!review)return current;const transfer=current.review||current.application;return{...current,title:current.title+' · 다른 상황',situation:transfer.situation,question:transfer.question,conditions:['앞서 배운 원리를 새로운 상황에 적용하는 복습입니다.'],options:transfer.options,answer:transfer.answer,core:transfer.explanation,judgment:'이 복습에 명시된 조건과 처음 배운 원리를 함께 적용합니다.',steps:[{title:'새 상황의 조건을 연결하기',text:transfer.explanation},{title:'처음 배운 원리',text:current.core},{title:'적용 범위 확인',text:current.boundaries}],evidence:null,simulation:null,perspectives:null,reflection:null,hints:['이 상황에서 주어진 조건과 판단해야 할 결론을 따로 정리해 보세요.','처음 배운 원리가 성립하는 조건을 이번 상황도 충족하는지 비교해 보세요.'],wrongReasons:transfer.options.map(()=>transfer.explanation)};}
function open(){if(!dialog.open){opener=document.activeElement;document.querySelector('#park-menu').open=false;dialog.showModal();document.body.classList.add('quiz-open');window.dispatchEvent(new Event('lab:open'));window.labSound?.('open');}}
function close(){dialog.close();}
dialog.addEventListener('close',()=>{document.body.classList.remove('quiz-open');window.dispatchEvent(new Event('lab:close'));opener?.focus?.();});document.querySelector('#close-learning').onclick=close;
function scrollTop(){dialog.scrollTo({top:0,behavior:'instant'});app.querySelector('h1')?.focus({preventScroll:true});}
function start(id,isReview=false){const q=items.find(q=>q.id===id);if(!q)return;current=q;review=isReview;screen='lesson';state.current={id,review};draft();persist();render();open();scrollTop();}
function catalog(){screen='catalog';current=null;render();open();scrollTop();}
function openRecords(){screen='records';current=null;render();open();scrollTop();}
document.querySelector('#open-library').onclick=catalog;document.querySelector('#open-memory').onclick=openRecords;document.querySelector('#start-featured').onclick=()=>{if(items.length)start('sci01');else catalog();};document.querySelector('#learning-back').onclick=catalog;
document.querySelector('.brand').onclick=e=>{e.preventDefault();close();document.body.classList.remove('has-walked');};
const card=q=>{const d=state.records[q.id];return`<button class="content-card" data-start="${q.id}"><span class="card-meta"><span>${esc(q.field)} · ${esc(q.type)}</span><span>${q.minutes}분</span></span><h2>${esc(q.title)}</h2><p>${esc(q.objective)}</p><span class="card-bottom"><span>${d?esc(learningChange(d)):['관찰부터','정보 연결','조건 비교'][q.difficulty-1]}</span><span>↗</span></span></button>`;};
function listCards(){const pool=items.filter(q=>(!featured||q.representative)&&(room==='all'||q.room===room)&&(!search||[q.title,q.question,q.field,...q.connections].join(' ').toLowerCase().includes(search.toLowerCase())));return pool.length?pool.map(card).join(''):'<p class="empty">조건에 맞는 콘텐츠가 없어요.</p>';}
function renderCatalog(){const resume=state.current&&items.find(q=>q.id===state.current.id),due=dueItems(items,state).length;return`<div class="library-heading"><div><span class="eyebrow">지식 연구소</span><h1 tabindex="-1">생각이 남는 질문들</h1><p>예상부터 해설, 다른 상황에 적용하기까지.</p></div><div class="catalog-count">${items.length}개 콘텐츠 · ${new Set(items.map(q=>q.field)).size}개 분야</div></div>${resume?`<div class="resume-banner"><span>이어서 보기 · ${esc(resume.title)}</span><button data-resume>계속하기 →</button></div>`:''}${due?`<div class="resume-banner"><span>다른 상황에서 다시 확인할 원리 ${due}개</span><button data-records>복습 보기 →</button></div>`:''}<div class="catalog-tools"><input class="search" id="search" type="search" aria-label="콘텐츠 검색" placeholder="궁금한 주제나 원리 검색" value="${esc(search)}"><button class="filter-toggle" data-featured aria-pressed="${featured}">${featured?'대표 12개':'전체 '+items.length+'개'}</button></div><div class="room-filters" aria-label="장소별 콘텐츠"><button data-room="all" class="${room==='all'?'active':''}">전체 장소</button>${rooms.map(r=>`<button data-room="${r.id}" class="${room===r.id?'active':''}">${r.name}</button>`).join('')}</div><div class="catalog" id="catalog-results">${listCards()}</div><p class="catalog-note">출처 대조일 2026.11.14 · AI 보조 편집 검토를 거쳤으며 독립 전문가 심사는 아직 받지 않았습니다.<br>학습 기록은 이 브라우저에 저장됩니다. ${cached?'연결이 불안정해 이전에 저장한 콘텐츠를 표시합니다.':''}</p>`;}
function options(q,d,application=false){return`<div class="options" role="group" aria-label="${application?'응용 문제':'질문'} 선택지">${q.options.map((o,i)=>{const chosen=application?d.applicationChoice:d.choice,done=application?Number.isInteger(chosen):d.committed,correct=done&&i===q.answer;return`<button class="option ${chosen===i?'selected':''} ${correct?'correct':''} ${done&&chosen===i&&!correct?'wrong':''}" ${done?'disabled':''} data-${application?'application':'choice'}="${i}" aria-pressed="${chosen===i}"><i>${i+1}</i><span>${esc(o)}</span>${done?(correct?`<em>${chosen===i?'내 선택 · 정답':'정답'}</em>`:chosen===i?'<em>내 선택 · 다시 보기</em>':''):chosen===i?'<em>내 선택</em>':''}</button>`;}).join('')}</div>`;}
function views(q){return q.perspectives?`<p class="distinction">비교의 성격 · ${esc(q.distinction)}</p><div class="perspectives">${q.perspectives.map(v=>`<section class="perspective"><h3>${esc(v.name)}</h3><dl>${[['claim','주장'],['evidence','근거'],['assumptions','전제'],['scope','설명 범위'],['limit','한계']].map(([k,l])=>`<dt>${l}</dt><dd>${esc(v[k])}</dd>`).join('')}</dl></section>`).join('')}</div>`:'';}
function simulation(q,d){const kind=q.simulation?.kind;if(!kind)return'';const s=d.simulation||(d.simulation={}),locked=d.choice===null&&!d.committed,disabled=locked?'disabled':'';let body='';
 if(kind==='coin'){const total=s.total||0,heads=s.heads||0;body=`<div class="sim-bars"><div style="--height:${total?heads/total*100:1}%"><span>${heads}</span></div><div style="--height:${total?(total-heads)/total*100:1}%"><span>${total-heads}</span></div></div><div class="sim-labels"><span>앞면</span><span>뒷면</span></div><div class="sim-controls"><button data-sim="coin" data-count="1" ${disabled}>1번 던지기</button><button data-sim="coin" data-count="100" ${disabled}>100번 반복</button><button data-sim="reset">초기화</button></div><p class="sim-result" aria-live="polite">${total?`${total}회 · 앞면 ${(heads/total*100).toFixed(1)}%`:'아직 던지지 않았어요.'} · 매번 앞면 확률 50%, 독립 시행 모형.</p>`;}
 if(kind==='monty'){body=`<div class="door-row">${[0,1,2].map(i=>`<button data-door="${i}" ${disabled||s.opened!==undefined?'disabled':''} class="${s.pick===i?'selected':''}">${i+1}번 문<br>${s.done?(s.prize===i?'상품':'염소'):s.opened===i?'염소':s.pick===i?'내 선택':'?'}</button>`).join('')}</div><div class="sim-controls">${s.opened!==undefined&&!s.done?'<button data-sim="monty-stay">유지하기</button><button data-sim="monty-switch">바꾸기</button>':''}<button data-sim="monty-batch" ${disabled}>전략별 1,000회 비교</button><button data-sim="reset">다시 실험</button></div><p class="sim-result" aria-live="polite">${s.done?(s.win?'선택한 문에 상품이 있어요.':'이번에는 염소였어요.'):s.opened!==undefined?'진행자가 상품이 없는 다른 문을 열었어요.':'예상한 뒤 문 하나를 고르세요.'}${s.batch?`<br>총 ${s.batch.total}회 · 유지 ${s.batch.stay}승 / 바꾸기 ${s.batch.change}승`:''}<br>진행자는 상품 위치를 알고, 항상 염소 문을 열고, 항상 바꿀 기회를 줍니다.</p>`;}
 if(kind==='bridge'){const key=s.key??true,lantern=s.lantern??false,open=bridgeOpen(key,lantern);body=`<div class="sim-controls"><label><input type="checkbox" id="sim-key" ${key?'checked':''} ${disabled}>열쇠</label><label><input type="checkbox" id="sim-lantern" ${lantern?'checked':''} ${disabled}>등불</label></div><div class="bridge-row">${open.map((v,i)=>`<div data-open="${v}">${['A','B','C'][i]} 다리<small>${v?'통과 가능':'닫힘'}</small></div>`).join('')}</div><p class="sim-result">A: 둘 다 있음 · B: 하나 이상 있음 · C: 둘 다 없음<br>실험으로 바꾼 조건은 문제의 조건을 바꾸지 않습니다. 답은 제시된 조건을 기준으로 골라 주세요.</p>`;}
 if(kind==='graph'){const base=s.zero?0:30;body=`<div class="sim-bars"><div style="--height:${barHeight(40,base)}%"><span>40</span></div><div style="--height:${barHeight(50,base)}%"><span>50</span></div></div><div class="sim-labels"><span>이전</span><span>이후</span></div><div class="sim-controls"><button data-sim="graph" ${disabled}>축을 ${s.zero?'30':'0'}부터 보기</button></div><p class="sim-result">세로축 범위 ${base}~50 · 실제 값은 40과 50으로 같습니다. 세로축의 시작에 따라 막대 길이 비율이 달라집니다.</p>`;}
 if(kind==='seasons'){const model=seasonModel(s.zero?0:23.44,s.month||'june');body=`<div class="orbit" aria-hidden="true"><div class="sun"></div><div class="earth ${s.zero?'zero':''}" style="${s.month==='dec'?'rotate:47deg':''}"></div></div><div class="sim-controls"><button data-sim="tilt" ${disabled}>기울기 ${s.zero?'23.44°':'0°'}로</button><button data-sim="month" ${disabled}>${s.month==='dec'?'6월 하지':'12월 동지'} 위치로</button></div><p class="sim-result">${s.month==='dec'?'12월 동지':'6월 하지'} · 기울기 ${s.zero?'0':'23.44'}°<br>북위 37° 낮 ${model.north.toFixed(1)}시간 · 남위 37° 낮 ${model.south.toFixed(1)}시간<br>원형 궤도, 일정한 축 방향, 대기 굴절을 생략한 기하 모형. 그림은 축척을 반영하지 않습니다.</p>`;}
 if(kind==='timbre'){body=`<div class="sound-comparison"><button data-sim="timbre-a" ${disabled}><span aria-hidden="true">∿</span>소리 1 듣기</button><button data-sim="timbre-b" ${disabled}><span aria-hidden="true">≋</span>소리 2 듣기</button></div><p class="sim-result" aria-live="polite">${s.audioError?'소리가 꺼져 있거나 사용할 수 없어요. 설정의 효과음을 확인해 주세요.':s.played?'두 소리의 높이와 질감을 비교해 보세요.':'예상한 뒤 두 소리를 들어 보세요.'}<br>기본 주파수는 모두 220 Hz입니다. 두 번째 소리에 440·660 Hz 성분을 더했습니다. 악기 녹음이 아닌 합성 모형이며 같은 지각 음량을 보장하지 않습니다.</p>`;}
 return`<section class="simulator" aria-label="직접 실험"><h3>직접 실험 · ${locked?'먼저 아래에서 예상해 주세요':'조건을 바꾸며 비교해 보세요'}</h3>${body}</section>`;
}
function related(q){const neighbors=items.filter(x=>x.id!==q.id).map(x=>({x,score:x.connections.filter(c=>q.connections.includes(c)).length*3+(x.field===q.field?1:0)})).sort((a,b)=>b.score-a.score).filter(x=>x.score>0).slice(0,3);return neighbors.length?'<h3>연결해서 볼 질문</h3>'+neighbors.map(({x})=>`<button class="text-button" data-start="${x.id}">${esc(x.title)} ↗</button>`).join(''):'';}
function explanation(q,d){if(!d.committed)return'';const correct=d.choice===q.answer;return`<section class="explanation" aria-label="정답과 해설"><div class="result-banner ${correct?'is-correct':'is-revisit'}"><span class="result-symbol" aria-hidden="true">${correct?'<svg viewBox="0 0 36 36"><circle cx="18" cy="18" r="15"/><path d="m11 18 5 5 10-11"/></svg>':'↺'}</span><h2 tabindex="-1">${correct?'근거를 확인해 볼까요':'선택을 다시 살펴볼까요'}</h2><span>${correct?'정답':'정답은 '+(q.answer+1)+'번'}</span></div><p class="core">${esc(q.core)}</p><p class="picked-reason"><strong>내 선택 · ${esc(q.options[d.choice])}</strong><br>${esc(q.wrongReasons[d.choice])}</p>${d.initial!==undefined?`<p class="review-note">새 증거 전 ${d.initial+1}번 → 확인한 판단 ${d.choice+1}번. ${d.initial===d.choice?'판단을 유지했어요.':'판단을 수정했어요.'}</p>`:''}<details><summary>자세히 이해하기</summary><div class="detail-content">${q.steps.map((s,i)=>`<div class="step"><span>0${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></div>`).join('')}<h3>다른 선택지도 그럴듯했던 이유</h3>${q.options.map((o,i)=>`<p><strong>${i+1}. ${esc(o)}</strong><br>${esc(q.wrongReasons[i])}</p>`).join('')}<h3>판정 기준</h3><p>${esc(q.judgment)}</p></div></details><details><summary>더 탐구하기 · 한계와 출처</summary><div class="detail-content"><h3>조건이 달라지면</h3><p>${esc(q.boundaries)}</p><h3>연결되는 원리</h3><p>${q.connections.map(esc).join(' · ')}</p>${related(q)}<h3>확인한 자료</h3><ol class="source-list">${q.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>${esc(s.locator)}<br>${esc(s.support)}</small></li>`).join('')}</ol><p class="review-note">확인일 ${esc(q.verification.reviewed)} · 출처 대조<br>${esc(q.verification.note)}</p><h3>학습 목표와 사전 지식</h3><p>${esc(q.objective)}<br>사전 지식: ${q.prerequisites.length?q.prerequisites.map(esc).join(', '):'없음'}</p></div></details>${q.reflection?`<p class="reflection">${esc(q.reflection)}</p>`:''}${!review?`<section class="transfer"><span class="eyebrow">다른 상황에 적용하기</span><h3>${esc(current.application.question)}</h3><p>${esc(current.application.situation)}</p>${options(current.application,d,true)}${Number.isInteger(d.applicationChoice)?`<div class="transfer-feedback" role="status">${d.applicationChoice===current.application.answer?'✓ 새 상황에도 적용했어요.':'조건을 다시 연결해 보세요.'}<br>${esc(current.application.explanation)}</div>`:''}</section>`:''}<div class="lesson-actions"><button class="secondary" data-records>학습 기록</button><button class="primary" data-next>다음 질문 →</button></div></section>`;}
function renderLesson(){const q=itemView(),d=draft();return`<article class="lesson"><div class="lesson-meta"><span class="type">${review?'짧은 복습':esc(q.type)}</span><span>${esc(q.field)}</span><span>${q.minutes}분</span><span>${['관찰부터','정보 연결','조건 비교'][q.difficulty-1]}</span><button class="save" data-save aria-pressed="${state.saved.includes(q.id)}">${state.saved.includes(q.id)?'저장됨':'저장'}</button></div><h1 tabindex="-1">${esc(q.title)}</h1><p class="situation">${esc(q.situation)}</p><ul class="conditions">${q.conditions.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${views(q)}${simulation(q,d)}${d.evidence&&q.evidence?`<aside class="evidence" aria-live="polite"><strong>새로운 증거</strong>${esc(q.evidence.text)}<p>${esc(q.evidence.prompt)}</p></aside>`:''}<h2 class="question">${esc(q.question)}</h2>${options(q,d)}<p class="choice-label">판단의 근거 <span>· 선택 사항, 자동 저장</span></p><textarea id="reason" class="reason-input" aria-label="판단의 근거" placeholder="어떤 조건이나 증거를 중요하게 봤나요?" maxlength="2000">${esc(d.note)}</textarea>${!d.committed?`<div class="lesson-actions"><button class="secondary" data-hint ${d.hints>=q.hints.length?'disabled':''}>힌트 ${Math.min(d.hints+1,q.hints.length)} / ${q.hints.length}</button><button class="primary" data-confirm ${d.choice===null?'disabled':''}>${q.evidence&&!d.evidence?'새 증거 확인':'이 판단으로 확인'}</button></div>${q.hints.slice(0,d.hints).map(h=>`<p class="hint">${esc(h)}</p>`).join('')}`:''}${explanation(q,d)}</article>`;}
function renderRecords(){const visited=items.filter(q=>state.records[q.id]),applied=visited.filter(q=>state.records[q.id]?.reviews?.at(-1)?.correct||state.records[q.id]?.application?.correct),due=dueItems(items,state);return`<div class="library-heading"><div><span class="eyebrow">기억 서재</span><h1 tabindex="-1">이해가 바뀐 기록</h1><p>처음의 판단과 새 상황에 적용한 결과를 함께 봅니다.</p></div></div><div class="progress-summary"><div><strong>${visited.length}</strong>풀어 본 원리</div><div><strong>${applied.length}</strong>응용까지 확인</div><div><strong>${due.length}</strong>다시 떠올릴 원리</div></div><div class="records">${visited.map(q=>{const r=state.records[q.id],first=r.attempts?.[0];return`<article class="record"><strong>${esc(q.title)}</strong><p>${esc(learningChange(r))}</p><p>최초 예상: ${(first?.initialCorrect??first?.correct)?'정답':'다시 확인'}${first?.initialChoice!==undefined&&first.initialChoice!==first.choice?' → 근거 확인 후 '+(first.correct?'정답':'다시 확인'):''} · 응용: ${r.application?.correct?'적용 성공':r.application?'다시 확인':'아직 안 함'} · 복습 ${r.reviews?.length||0}회</p><p>${r.due<=Date.now()?'복습할 때가 되었어요.':'다음 복습 '+new Date(r.due).toLocaleDateString('ko-KR')}</p><button data-review="${q.id}">새 상황으로 복습하기 ↗</button> <button data-start="${q.id}">이전 해설 보기</button></article>`;}).join('')||'<div class="empty">질문을 풀면 판단과 응용 결과가 여기에 남아요.</div>'}</div>${state.saved.length?`<h2 style="margin:30px 0 20px;font-size:20px">저장한 질문</h2><div class="catalog">${items.filter(q=>state.saved.includes(q.id)).map(card).join('')}</div>`:''}<p class="catalog-note">정답 확인 다음날 또는 3일 뒤에 복습을 제안합니다. 새 상황의 응용 문제를 사용하며, 같은 원리를 충분히 익힌 뒤에는 반복을 강요하지 않습니다. 기록은 기기 간 동기화되지 않습니다.</p>`;}
function render(){const active=document.activeElement;let focusSelector=active?.id?'#'+active.id:null;if(!focusSelector&&active?.dataset){for(const key of ['sim','door','room','hint','featured'])if(active.hasAttribute('data-'+key)){focusSelector='[data-'+key+'="'+active.getAttribute('data-'+key)+'"]';if(active.dataset.count)focusSelector+='[data-count="'+active.dataset.count+'"]';break;}}document.querySelector('#learning-title').textContent=screen==='lesson'?roomName(current.room):screen==='records'?'기억 서재':'학습실';document.querySelector('#learning-back').hidden=screen==='catalog';app.innerHTML=error?`<div class="empty">${esc(error)}<button data-retry>다시 불러오기</button></div>`:!items.length?'<div class="empty" role="status">출처와 해설을 불러오고 있어요.</div>':screen==='lesson'?renderLesson():screen==='records'?renderRecords():renderCatalog();if(focusSelector){const target=app.querySelector(focusSelector);if(target&&!target.disabled)target.focus({preventScroll:true});}}
function updateSimulation(fn){const d=draft();fn(d.simulation||(d.simulation={}));persist();const old=dialog.scrollTop;render();dialog.scrollTop=old;}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.start)start(b.dataset.start);if(b.dataset.review){delete state.drafts[b.dataset.review+'-review'];start(b.dataset.review,true);}if(b.hasAttribute('data-records'))openRecords();if(b.hasAttribute('data-resume')&&state.current)start(state.current.id,state.current.review);
 if(b.hasAttribute('data-featured')){featured=!featured;render();}if(b.dataset.room){room=b.dataset.room;featured=false;render();}if(b.hasAttribute('data-retry'))initialize();
 if(!current)return;const d=draft(),q=itemView();
 if(b.dataset.choice!==undefined&&!d.committed){d.choice=+b.dataset.choice;persist();const y=dialog.scrollTop;render();dialog.scrollTop=y;app.querySelector(`[data-choice="${d.choice}"]`)?.focus({preventScroll:true});window.labSound?.('select');}
 if(b.hasAttribute('data-confirm')&&d.choice!==null&&!d.committed){if(q.evidence&&!d.evidence){d.initial=d.choice;d.evidence=true;}else{d.committed=true;recordAnswer(state,current,d.choice,{review,initialChoice:d.initial??d.choice});window.labSound?.(d.choice===q.answer?'correct':'wrong');}persist();const y=dialog.scrollTop;render();dialog.scrollTop=y;if(d.committed){app.querySelector('.explanation')?.scrollIntoView({block:'start',behavior:'instant'});app.querySelector('.result-banner h2')?.focus({preventScroll:true});}else app.querySelector('.evidence')?.scrollIntoView({block:'center',behavior:'instant'});}
 if(b.hasAttribute('data-hint')){d.hints++;persist();const y=dialog.scrollTop;render();dialog.scrollTop=y;}
 if(b.hasAttribute('data-save')){state.saved=state.saved.includes(q.id)?state.saved.filter(id=>id!==q.id):[...state.saved,q.id];persist();b.textContent=state.saved.includes(q.id)?'저장됨':'저장';b.setAttribute('aria-pressed',state.saved.includes(q.id));}
 if(b.dataset.application!==undefined&&!Number.isInteger(d.applicationChoice)){d.applicationChoice=+b.dataset.application;state.records[current.id].application={choice:d.applicationChoice,correct:d.applicationChoice===current.application.answer,at:Date.now()};persist();const y=dialog.scrollTop;render();dialog.scrollTop=y;app.querySelector('.transfer-feedback')?.scrollIntoView({block:'nearest',behavior:'instant'});}
 if(b.hasAttribute('data-next')){const pool=items.filter(x=>x.room===current.room&&x.id!==current.id);const next=pool.find(x=>!state.records[x.id])||items.find(x=>!state.records[x.id])||pool[0];if(next)start(next.id);else catalog();}
 if(b.dataset.sim){const action=b.dataset.sim;if(action.startsWith('timbre-')){const id=current.id;Promise.resolve(window.labTone?.(action==='timbre-a'?'pure':'rich')).then(ok=>{if(current?.id===id)updateSimulation(s=>{s.played=!!ok;s.audioError=!ok;});});return;}updateSimulation(s=>{if(action==='reset')d.simulation={};if(action==='coin'){Object.assign(s,toss(s,+b.dataset.count,.5));window.dispatchEvent(new CustomEvent('lab:simulation',{detail:{kind:'coin'}}));}if(action==='graph')s.zero=!s.zero;if(action==='tilt')s.zero=!s.zero;if(action==='month')s.month=s.month==='dec'?'june':'dec';if(action==='monty-batch')s.batch=montyBatch(1000);if(action==='monty-stay'||action==='monty-switch'){const final=action==='monty-stay'?s.pick:[0,1,2].find(i=>i!==s.pick&&i!==s.opened);s.done=true;s.win=final===s.prize;}});}
 if(b.dataset.door!==undefined){updateSimulation(s=>{if(s.opened!==undefined)return;s.pick=+b.dataset.door;s.prize=Math.floor(Math.random()*3);const goats=[0,1,2].filter(i=>i!==s.pick&&i!==s.prize);s.opened=goats[Math.floor(Math.random()*goats.length)];});}
});
app.addEventListener('input',e=>{if(e.target.id==='reason'){draft().note=e.target.value;persist();}if(e.target.id==='search'){search=e.target.value;app.querySelector('#catalog-results').innerHTML=listCards();}if(['sim-key','sim-lantern'].includes(e.target.id)){const key=app.querySelector('#sim-key').checked,lantern=app.querySelector('#sim-lantern').checked;updateSimulation(s=>{s.key=key;s.lantern=lantern;});window.dispatchEvent(new CustomEvent('lab:simulation',{detail:{kind:'bridge',key,lantern}}));}});
dialog.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(screen==='lesson'&&['1','2','3','4'].includes(e.key)){const b=app.querySelector(`[data-choice="${+e.key-1}"]`);if(b&&!b.disabled){e.preventDefault();b.click();}}});
let discovery=null;window.showParkDiscovery=r=>{const element=document.querySelector('#discovery-card');if(!r||!items.length){element.hidden=true;return;}const pool=items.filter(q=>r.fields?.length?r.fields.includes(q.field):q.room===(r.room||r.id));discovery=pool.find(q=>!state.records[q.id])||pool[0];if(!discovery){element.hidden=true;return;}document.querySelector('#discovery-field').textContent=r.name;discovery={...discovery,openReview:!!r.review};document.querySelector('#discovery-question').textContent=discovery.title;element.hidden=false;window.labSound?.('discover');};
document.querySelector('#open-discovery').onclick=()=>{if(discovery){if(discovery.openReview&&Object.keys(state.records).length)openRecords();else start(discovery.id);}};document.querySelector('#dismiss-discovery').onclick=()=>window.dismissParkDiscovery?.();
const motion=document.querySelector('#motion');let reduced=false;try{reduced=storage.getItem('lab-motion')==='reduce';}catch{}function motionLabel(){document.body.classList.toggle('still',reduced);motion.setAttribute('aria-pressed',reduced);motion.textContent=reduced?'켬':'끔';}motion.onclick=()=>{reduced=!reduced;motionLabel();try{storage.setItem('lab-motion',reduced?'reduce':'full');}catch{}};motionLabel();
async function initialize(){if(loadPending)return;loadPending=true;error='';render();try{const result=await loadCatalog({storage});items=result.items;cached=result.cached;window.dispatchEvent(new Event('lab:content-ready'));}catch(e){error=e.message;}finally{loadPending=false;render();}}
const worldTool=document.querySelector('#world-experiment');window.openWorldExperiment=()=>{soundTool.hidden=true;window.dispatchEvent(new Event('lab:pause'));worldTool.hidden=false;document.querySelector('#world-key').focus();};document.querySelector('#close-world-experiment').onclick=()=>worldTool.hidden=true;document.querySelector('#world-bridge-question').onclick=()=>{worldTool.hidden=true;start('rea03');};for(const id of ['world-key','world-lantern'])document.querySelector('#'+id).addEventListener('change',()=>{const key=document.querySelector('#world-key').checked,lantern=document.querySelector('#world-lantern').checked;document.querySelector('#world-bridge-result').textContent=bridgeOpen(key,lantern).map((v,i)=>['A','B','C'][i]+(v?' 열림':' 닫힘')).join(' · ');window.dispatchEvent(new CustomEvent('lab:simulation',{detail:{kind:'bridge',key,lantern}}));});
initialize();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

const soundTool=document.querySelector('#sound-experiment');window.openSoundExperiment=()=>{worldTool.hidden=true;window.dispatchEvent(new Event('lab:pause'));soundTool.hidden=false;soundTool.querySelector('[data-world-tone]').focus();};document.querySelector('#close-sound-experiment').onclick=()=>soundTool.hidden=true;document.querySelector('#world-sound-question').onclick=()=>{soundTool.hidden=true;start('per08');};soundTool.querySelectorAll('[data-world-tone]').forEach(b=>b.onclick=async()=>{const ok=await window.labTone?.(b.dataset.worldTone);document.querySelector('#world-sound-result').textContent=ok?'기본 음높이는 같고, 배음 구성이 달라요.':'설정에서 효과음을 켜고 다시 들어 주세요.';});

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(!worldTool.hidden||!soundTool.hidden)){worldTool.hidden=true;soundTool.hidden=true;document.querySelector('#park-canvas').focus({preventScroll:true});}});
